{"name": "bash", "args": {"command": "python3 - <<'EOF'
import json, re, sys
from urllib.parse import urlparse

with open("data/spots.json", encoding="utf-8") as f:
    spots = json.load(f)

assert isinstance(spots, list), "not a list"
print("rows:", len(spots))
ok = 20 <= len(spots) <= 40
print("20-40 rows:", ok)

REQ = ["id","name","city","country","type","capybara_experience","hours","adult_price","source_url","verified_on"]
TYPES = {"zoo","onsen","cafe","sanctuary","farm","park"}
ids, errors = set(), []
for i, s in enumerate(spots):
    for k in REQ:
        if k not in s: errors.append(f"row {i}: missing {k}")
        elif not isinstance(s[k], str): errors.append(f"row {i}: {k} not string")
    if "id" in s:
        if not re.fullmatch(r"[A-Za-z0-9._-]+", s["id"]): errors.append(f"row {i}: id not url-safe slug: {s['id']}")
        if s["id"] in ids: errors.append(f"row {i}: dup id {s['id']}")
        ids.add(s["id"])
    if s.get("country","") != s.get("country","").upper() or not re.fullmatch(r"[A-Z]{2}", s.get("country","")):
        errors.append(f"row {i}: bad country {s.get('country')!r}")
    if s.get("type") not in TYPES: errors.append(f"row {i}: bad type {s.get('type')!r}")
    u = s.get("source_url","")
    p = urlparse(u)
    if p.scheme not in ("http","https") or not p.netloc: errors.append(f"row {i}: bad source_url {u!r}")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s.get("verified_on","")): errors.append(f"row {i}: bad verified_on {s.get('verified_on')!r}")
    if not s.get("name") or not s.get("city"): errors.append(f"row {i}: empty name/city")

countries = sorted({s["country"] for s in spots})
types = sorted({s["type"] for s in spots})
print("countries:", countries)
print("types:", types)
print("verified_on range:", min(s["verified_on"] for s in spots), "->", max(s["verified_on"] for s in spots))
print("errors:", errors if errors else "none")
